-- CAREEROS P5-T04: email templates per application stage (PRODUCT.md 6.2). The CREATE TABLE, index and foreign key
-- statements are generated by drizzle-kit; row-level security and grants are written by hand, following P3-T08. Runs as
-- the migration (owner) role. Down migration: down.sql in this folder.
CREATE TABLE "email_template" (
	"id" text PRIMARY KEY,
	"organization_id" text NOT NULL,
	"user_id" text,
	"kind" text NOT NULL,
	"stage_category" text,
	"name" text NOT NULL,
	"subject" text NOT NULL,
	"body" text NOT NULL,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "email_template_kind_check" CHECK ("kind" in ('follow_up', 'thank_you', 'networking', 'negotiation', 'custom')),
	CONSTRAINT "email_template_stage_check" CHECK ("stage_category" is null or "stage_category" in ('saved', 'applied', 'screening', 'interview', 'offer', 'closed')),
	CONSTRAINT "email_template_name_check" CHECK (char_length(btrim("name")) between 1 and 100),
	CONSTRAINT "email_template_subject_check" CHECK (char_length(btrim("subject")) between 1 and 300),
	CONSTRAINT "email_template_body_check" CHECK (char_length("body") <= 10000)
);
--> statement-breakpoint
CREATE INDEX "email_template_org_user_idx" ON "email_template" ("organization_id","user_id","archived_at");--> statement-breakpoint
ALTER TABLE "email_template" ADD CONSTRAINT "email_template_organization_id_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization"("id") ON DELETE CASCADE;--> statement-breakpoint
ALTER TABLE "email_template" ADD CONSTRAINT "email_template_user_id_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE CASCADE;
--> statement-breakpoint
-- Row-level security (D4), exactly as P1-T04, P4-T01 and P3-T08: FORCE applies the policy to the table owner too, so
-- only owner_access lets the owner role (migrations, definer functions) see every organization. careeros_app only
-- matches its own organization; an unset setting is NULL and matches nothing (fail closed). The per-person rule (a
-- member reads the organization's defaults and only their own rows) is applied by the API on top of this.
ALTER TABLE "email_template" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "email_template" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "email_template";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "email_template"
	USING ("organization_id" = current_setting('app.current_org_id', true))
	WITH CHECK ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "email_template";--> statement-breakpoint
CREATE POLICY "owner_access" ON "email_template" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- Table privileges for the app role. The bootstrap's default privileges already cover tables the owner creates; this
-- grant makes the migration correct on a database where the roles were created differently. Idempotent.
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT SELECT, INSERT, UPDATE, DELETE ON "email_template" TO careeros_app;
	END IF;
END $$;
